/**
 * Builds lib/projectImages.generated.ts from whatever is sitting in
 * public/images/projects/<slug>/.
 *
 * The point is that adding a screenshot means dropping a file in a folder —
 * no TypeScript to edit, no path to type twice. Runs automatically before
 * `npm run dev` and `npm run build`, so the generated file can never drift
 * from the folder for long.
 *
 * Ordering is by filename, so numbered prefixes (01-, 02-) decide which shot
 * is the cover and how the gallery reads.
 */
import { readdirSync, readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const imagesDir = join(root, "public", "images", "projects");
const dataFile = join(root, "lib", "data.ts");
const outFile = join(root, "lib", "projectImages.generated.ts");

const EXT = /\.(jpe?g|png|webp|avif|gif)$/i;

/** Must match projectSlug() in lib/data.ts. */
const slugify = (s) =>
  s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

// Project titles, so a misspelled folder is reported instead of silently ignored
const titles = [...readFileSync(dataFile, "utf8").matchAll(/^\s{4}title: "(.+?)",$/gm)].map(
  (m) => m[1],
);
const known = new Map(titles.map((t) => [slugify(t), t]));

if (!existsSync(imagesDir)) mkdirSync(imagesDir, { recursive: true });

const folders = readdirSync(imagesDir, { withFileTypes: true })
  .filter((d) => d.isDirectory())
  .map((d) => d.name)
  .sort();

const entries = [];
const unknown = [];

for (const folder of folders) {
  const files = readdirSync(join(imagesDir, folder))
    .filter((f) => EXT.test(f))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

  if (files.length === 0) continue;
  if (!known.has(folder)) unknown.push(folder);

  entries.push([folder, files.map((f) => `/images/projects/${folder}/${f}`)]);
}

const body = entries
  .map(
    ([slug, paths]) =>
      `  "${slug}": [\n${paths.map((p) => `    "${p}",`).join("\n")}\n  ],`,
  )
  .join("\n");

writeFileSync(
  outFile,
  `// Generated by scripts/sync-project-images.mjs — do not edit by hand.
// Add screenshots under public/images/projects/<slug>/ and this file catches up
// on the next \`npm run dev\` or \`npm run build\`.

export const projectImages: Record<string, string[]> = {
${body}
};
`,
);

const total = entries.reduce((n, [, p]) => n + p.length, 0);
console.log(`sync-project-images: ${total} image(s) across ${entries.length} project(s)`);

for (const folder of unknown) {
  console.warn(
    `sync-project-images: WARNING folder "${folder}" matches no project title — ` +
      `check the spelling against lib/data.ts`,
  );
}

const missing = [...known.entries()].filter(([slug]) => !entries.some(([s]) => s === slug));
if (missing.length) {
  console.log(
    `sync-project-images: no images yet for ${missing.map(([s]) => s).join(", ")} ` +
      `(these fall back to the generated schematic)`,
  );
}
